exec((__import__('pathlib').Path(__file__).parent/'gaosi_a.py').read_text(encoding='utf-8').split("B('01出术'")[0])
B('28妖女煞星',[
C('he_qiu','何求','何求是靠上一代遗产生活的富家子弟，年纪已不轻，却很少认真做事，熟悉的是享乐和日常应酬。勒索信要求二十万元，他本想不理，电话里对方却能说出近日一举一动，于是相信这是可随时取命的大煞星。他没有报警，而未经商量就报出高斯的姓名和地址，把熟识但不算亲近的摄影家选作送钱人；见面时苦求帮忙，留下钱便逃走，自己的恐惧因此转成别人承担的危险。高斯被来取钱的女孩射伤，警方又从钱中发现精制伪钞，案件才进入他家。他始终相信父亲的钱来路正当，甚至在专业检验前坚持维护家族名誉，随后却接连得知儿子就是勒索者、父亲留下的现金与地下设备都来自伪钞犯罪。儿子因误会警方来抓自己而跳楼受伤，自述把将来的遗产当成现在就该得的钱；父亲则早已死亡，无法再回答他的质问。终局警方倾向认为何求并不知情，他自身未被明确判罪，仍须承受生活基础崩塌的痛苦。卡片保留他胆怯、自利、信任体面的缺陷，也允许其在真相后学习承担责任；遗产不再是无限安全资金，假钞不能当通用财富使用。','被查明卷入伪钞与亲子勒索案，警方认为可能无辜；父亲罪行曝光、儿子受伤自认勒索。','穿名贵西装的中年富家子弟；初到高斯家时淋湿、脸色苍白、口唇发抖。','保住性命、安稳生活与父亲留下的家族体面。','遇威胁先付钱并把风险交给熟人，遭硬证据时陷入震惊。','日常社交与委托关系；财产来源受案件限制，无侦查或战斗专长。',[(64,168,'生活背景、求助、擅自安排'),(520,626,'遗产现金与维护父亲'),(648,709,'儿子供述、地下设备与终局')],[('陌生人知道私人生活细节','自己尚未核验消息来源','容易高估对方力量，以付钱求平安。'),('朋友可能替自己承担风险','急于摆脱威胁','会先安排后求情，需要正面指出责任。'),('可信检测反驳家族叙事','证据逐项变得无法回避','由维护体面转为痛苦追问，不会立即变成熟练侦探。')],roles=['单书主角']),
C('he_qiu_son','何求的儿子','何求的儿子没有获得原文姓名，却以大煞星这个夸张署名成为勒索案的真正发起者。他穿新潮服饰、留长发，在父亲眼里只是缺少礼貌的年轻人；正因为生活在同一家中，他能准确讲出父亲的行动，让本来寻常的亲属信息看起来像无孔不入的监视。勒索信用剪贴字隐去笔迹，电话故意表现得凶狠急躁，再指定高斯代收、让女友上门取钱，避免自己直接面对摄影家。他为女友买了手枪，实际行动却远没有署名显示的老练，女友在紧张中开枪伤人，钱未到手，警方反而发现现金的另一重秘密。他看见警员在家里，误以为自己已经被识破，惊慌跳楼受伤，随后写出供述，解释父亲有那么多钱，遗产反正以后属于自己，所以先取一点也无妨。这个自我开脱把未来可能继承误作现有权利，却没有证明他知道祖父印伪钞。终局他已承认勒索，身体受伤，判决未写。可调用的是熟人信息、隐瞒身份和以权利感合理化索取的逻辑，不是专业杀手或神秘监视网；警方出现时的误判也会使他过早自毁布局。','跳楼跌伤后写信承认勒索；未来刑罚未交代。','长发，窄裤花衬衫，吹口哨进屋的年轻男子。','提前取得父亲的钱，把可能的遗产权当作现在索取的正当性。','隔着电话装凶狠，见警方近身便恐慌逃避。','利用家庭日常信息、剪贴匿名信和电话威胁；能购枪不等于枪法熟练。',[(86,104,'勒索信及电话要求'),(189,204,'粗哑电话催逼'),(488,496,'外观与父子关系'),(656,682,'跳楼、自供及买枪')],[('掌握家人的私人行程','对方不知道消息来自同住关系','把日常信息包装成外部监视能力。'),('自己缺钱而家人富有','把未来继承视作既定','可能用早晚属于自己来合理化侵占。'),('警察出现在家庭现场','尚不知其调查目的','容易因心虚认定自己暴露，仓促逃避。')],roles=['反派'],aliases=['大煞星'],deployment='以终局自供和骗局败露的记忆综合登场；跳楼伤势不能默认立即痊愈，需按场景给予恢复过程。'),
C('he_son_girlfriend','大煞星派出的收款女孩','这名约十六七岁的女孩是何求儿子的女友，受他安排前往高斯住处收取勒索款。她浓妆打扮，努力表现得老练，真正开口时却声音尖细、呼吸急促，一面催拿钱一面向后张望，比房主更加紧张。高斯凭她年轻和不熟练的样子，迅速从恐惧转成轻视，随口说身后没有警探，这句话反而触动她最担心的事。她从手袋取出男友买来的手枪，对准高斯；高斯又把枪误当玩具，伸手要夺，她立即开枪，使他肩部受伤，随后逃离，没有拿到钱。整个短暂相遇说明她既不是训练有素的职业枪手，也不是无害的装腔者，普通人手里真实的武器足以让错误判断造成流血。后来男友受伤自供，说明她与勒索者的关系，原文却没有交代她的逮捕或判决，不能因标题叫妖女就添加魅惑或超常能力。终局综合形态保留做坏事时的紧张和由惊恐升级为危险动作的可能，也不把一次开枪写成必然再次杀人的程序；若有人降低误判、拉开距离或明确退出，她仍可选择停止。','开枪伤高斯后逃走，未收得勒索款；男友随后供述关系，个人结局未写。','约十六七岁，个子较矮、浓妆，携带手袋；故作老练但明显紧张。','按男友安排取得勒索款并尽快离开现场。','担心被警察发现，受刺激后从催促转为持枪。','真实手枪的近距离使用；没有枪法精度、长期训练或超能力证据。',[(226,274,'年龄、打扮、紧张与拔枪'),(275,302,'高斯误判、枪伤与逃离'),(656,682,'男友身份和供述')],[('进入陌生人的住所收款','任务违法且缺少经验','急催交付并不断观察身后。'),('别人提到警察','自己本来就害怕暴露','可能误判为陷阱，亮出已有武器。'),('对方突然伸手夺枪','心理紧张且枪已在手','存在惊慌开枪的危险；不能保证命中或免于后果。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':2,'combat':1},tier='纸',limits='手枪须实际持有且有弹药；只证明一次近距离射伤，不赋予神枪手或专业杀手水平。'),
C('he_qiu_father','何求的父亲','何求的父亲在本案开始前已经死亡，留下的是儿子深信不疑的正当生意形象、一所老宅和数额庞大的现金。临终时他特别叮嘱儿子不要把现金存进银行，这个要求最初被当作家中习惯，直到警方检查勒索款，才成为隐藏来源的关键线索。老宅地下后来发现印制钞票的机器，警方确认他才是多年未能查明身份的伪钞专家。过去他把伪钞销往海外，本地案件很少；儿子继承后不知真伪地使用，精良印刷又让钱长期难以被普通人识破，最终一次二十万元的交付扩大了暴露。文本没有他生前出场的对话、外观或具体制版过程，也没有证实儿子参与制造，因此卡片只能从遗物、遗言与揭案事实反映他的谋划，不替他编造慈父动机或独门技术细节。终局他已经死亡，家族体面被推翻，未完成的犯罪收益也不能当成合法无穷资产。若以回溯形态登场，他仍须依靠真实机器、材料和销赃渠道，印刷经验不是凭空生成货币的能力，更无法保证在新社会的验钞制度下继续成功。','死后被查明为伪钞制造源头，地下机器被发现；在世时的司法结果不存在。','仅通过回述与遗物出现，外貌年龄不详，不补造影像。','隐瞒伪钞来源并延续其现金安排；更深个人动机未写。','已知策略是减少本地流通并叮嘱现金不入银行，避免常规核验。','精良伪钞制作与海外销售的历史经验；依赖机器、材料和渠道，不提供现实操作细节。',[(606,626,'现金遗产及临终叮嘱'),(648,654,'专业检验'),(688,709,'地下设备、源头及海外销售')],[('财产来源经不起公开核验','可用私人保管替代银行','倾向维持现金和隐蔽渠道。'),('技术成品已骗过普通使用者','仍存在专业检测','不能把成功经验视为永远无法识破。'),('后继者不了解真正风险','仍要交代财物','可能只给规避规则而不说明原因，使后人继续暴露。')],roles=['反派','已故源头人物'],revive=True,confidence='medium',uncertainties=['个人动机及生前性格证据有限，卡片只采用遗言与已证实犯罪策略。'])],excluded=[{'name':'何求两名得力伙计','reason':'电影院追人是奉主人寻高斯，误会不构成犯罪反派，且无跨书个人身份。'},{'name':'老仆、医院护士、鉴钞人员','reason':'一次性协助和信息角色，没有独立主角线。'}])
B('29预告',[
C('xu_qianjun','许千钧','许千钧是一家撞球场的老板，妻子与花花公子陈生保有暧昧关系，使他萌生杀意，却没有选择直接袭击目标。他以撞球般的间接路线安排杀人：先向穷画家戚云寄送连续七天的谋杀预告照片，再将画家杀死。照片看似从真实卧室天花板垂直拍摄，实际利用仿造布景和特殊视角造成错觉，又留下可把怀疑引向布景师陈生发的线索。陈生发与死者曾因酬劳争吵，足以让调查者先形成一个方便的答案；但他即将继承巨额遗产，查下去又会使警方怀疑候补继承人陈生保，恰好把真正仇人送进杀人嫌疑。许千钧愿意杀一个与报复目的无关的人，只为让司法程序走向自己希望的结局，周密之处也建立在他预计别人会如何推理。高斯通过陈生保谈起的威胁与撞球场职业，和李玉芳共同重建这条连锁路线；许千钧被捕后承认罪行。终局他不是能预知警察每一步的神人，曾经成功设局也不能保证新事件照剧本发展。人物应在嫉妒、控制欲和谋划之间保持张力，遇到拒绝把嫌疑当定论的调查者，他必须面对布局被反向追索的风险。','被警方拘捕并承认罪状。','撞球场老板，具体衣饰相貌未写；威胁由陈生保转述。','报复与妻子有暧昧关系的陈生保，让其承担杀人罪后果。','避免直接冲突，用多层误导操纵调查方向。','布置误导证据和预估他人推理的谋划；非预知、命运控制或强制司法权。',[(122,158,'连续预告与真实谋杀'),(382,425,'仿造布景及第一层嫌疑'),(636,674,'动机、连锁布局与承认')],[('报复对象直接受害会指向自己','能够选择无关中间对象','可能绕道制造更长因果链以遮蔽动机。'),('调查者倾向接受一个完整故事','能够留下似乎恰好的线索','先喂出便于相信的嫌疑，再利用推翻它后的方向。'),('各层推理被放到一起核验','自己与终点目标的私人关系暴露','布局可能反成证据，不能靠聪明称号脱罪。')],roles=['反派'],scores={'physical':1,'energy':0,'scope':1,'sustain':1,'range':0,'combat':1},tier='纸',uncertainties=['实际搭景的逐步实施过程未展示，不额外赋予专业摄影或全套舞台工艺。']),
C('chen_shengfa','陈生发','陈生发是小型电影公司的布景师，也有摄影棚主管的工作条件。穷画家戚云曾替他画布景，两人因为报酬多少争吵，戚云指责他苛扣应得的钱，此后不再来工作。这个有旁人见证的矛盾，在伪造卧室照片被识别为布景后，几乎使所有表面线索都指向他：他有技术、场地、时间，又像是有仇恨。被扣留时，他始终否认谋杀，说争吵早已忘记；高斯却把他的憔悴和愤怒都继续解释为罪证。他提出自己即将继承富有堂伯的遗产，为什么要为一个穷画家冒杀人风险，这不是财富使人免罪，而是要求警方核实另一个事实。李玉芳查到遗嘱、重病长辈与候补继承人，才看出陈生发更可能是布局中的被害对象。真凶许千钧最终被捕，陈生发的杀人嫌疑得以澄清，未来是否实际获得遗产没有写。角色仍可能在工作关系中苛刻或轻视穷人，洗清谋杀并不自动证明他对戚云公平；与此同时，他的愤怒也不能再被当作天生杀人的证据。可调用能力限于布景职业和真实工作权限，遗产只是一项尚未兑现的法律安排。','许千钧被捕承认后谋杀嫌疑澄清；继承是否实际发生未写。','布景师，被扣留后憔悴、声音嘶哑，激动时握拳。','洗脱未犯的杀人指控，守住即将继承财产的生活前景。','反复否认并提出可查事实，被固执误解后愤怒。','布景工作与摄影棚管理经验；有条件接触场地不等于实施了伪证。',[(420,425,'职业及酬劳争执'),(494,567,'扣留、否认及继承事实'),(574,596,'候补继承人及陷害假说'),(659,674,'真正布局与结案')],[('调查把既有口角解释为谋杀动机','自己认为争执已过','强调时间和现实利益，要求核实而非只看情绪。'),('被误解后每次反抗都被当作证据','耐心被持续消耗','可能愤怒握拳，仍不等于会实施杀人。'),('得到有利的遗嘱消息','财产尚未实际交付','可能提前以未来富翁自居，暴露阶层轻视。')],roles=['单书主角','阶段性嫌疑人']),
C('chen_shengbao','陈生保','陈生保是衣着入时、喷洒香水的花花公子，也是富有长辈遗嘱中的候补继承人。警方发现陈生发若无法继承，他就可能取得财产，因而一度认为他有最合逻辑的动机去杀戚云、陷害陈生发。这一层推断恰是许千钧布局所需，却并不是陈生保真的做过谋杀的证明。李玉芳安排人员假装围攻，再由高斯及时解围，试图在放松警惕的交谈里找出线索；陈生保以为袭击来自与自己有私人恩怨的许千钧，脸色发白，一再要求警方保护。他解释自己与许妻有暧昧关系，又把责任全推给女方主动勾引，强调许千钧该怨妻子而非自己，显出怕死和卸责的一面。高斯试探巧妙杀人的话，他几乎没听进去，只反复谈真实害怕的威胁，反而给出了破案所需的最后关系。终局许千钧承认罪行，陈生保不是幕后的深谋远虑者，遗产也没有自动落到他手中。角色可以自私、轻佻并造成关系伤害，同时仍是被谋害的对象；不应因生活作风就给他增加未证实的杀人能力。','间接陷害被识破，许千钧被捕；候补继承利益未兑现。','衣着时髦、使用香水的成年男子，遇袭后面色苍白。','享受生活并避免许千钧的报复，危急时寻求警方保护。','惊恐时反复诉说威胁，倾向把暧昧责任推给他人。','社交生活与具体人际信息；没有侦查、战斗或犯罪布局专长证据。',[(574,612,'候补继承与警方怀疑'),(616,648,'假救援、私人关系及恐惧'),(659,674,'其实际被陷害的位置')],[('有人攻击自己','已听到特定人的杀意威胁','先按私人恩怨解释，要求保护。'),('被问及暧昧关系责任','担心失去同情','强调是对方主动，把自己描述为无辜承受者。'),('救命者提出绕弯的试探','注意仍被恐惧占据','可能忽略话中诱导，只反复说自己真正害怕的事。')],roles=['单书主角','阶段性嫌疑人'])],excluded=[{'name':'戚云','reason':'本篇核心受害者，绘画职业、报案与死亡均由他人回述；没有独立主角视角、反派行为或跨书经历，作为案件证据人物保留。'},{'name':'许千钧之妻','reason':'通过陈生保转述出现，未证实知情参与谋杀；不因暧昧关系直接列反派。'},{'name':'伪装袭击陈生保的警方人员','reason':'警方演示行动，未具个人身份，不误列犯罪团伙。'}])
(P/'gaosi_i.draft.json').write_text(json.dumps(books,ensure_ascii=False,indent=2),encoding='utf-8')
